<script setup lang="ts">
const {staff,mutate}=useStaff(); const error=ref('');
async function logout(){try{await mutate('/api/auth/logout',{method:'POST'});staff.value=null;await navigateTo('/admin/login');}catch(e){error.value=errorMessage(e);}}
</script>
<template><div class="admin-shell"><header class="admin-header"><NuxtLink to="/" class="brand"><img src="/brand/uniformes-ellas.png" alt="Uniformes Ellas" width="140" height="46" /></NuxtLink><NuxtLink to="/admin/solicitudes" class="admin-panel-label">Panel del equipo <span class="badge">DEMO</span></NuxtLink><NuxtLink v-if="staff?.role==='admin'" to="/admin/asistente" class="text-link">Asistente del equipo <AppIcon name="ArrowUpRight" :size="15"/></NuxtLink><div class="admin-user"><span>{{ staff?.name }}</span><button class="icon-button" aria-label="Cerrar sesión" @click="logout"><AppIcon name="LogOut" /></button></div></header><p v-if="error" class="alert error">{{error}}</p><main id="main" class="admin-main"><slot /></main><footer class="admin-footer">Entorno de demostración · Las solicitudes marcadas como «Ejemplo» son ficticias. <NuxtLink to="/">Volver a la web <AppIcon name="ArrowUpRight" :size="14" /></NuxtLink></footer></div></template>
